CREATE TABLE trg17_members (member_id INTEGER PRIMARY KEY, member_name TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE trg17_member_deletes (audit_id INTEGER PRIMARY KEY, member_id INTEGER NOT NULL, member_name TEXT NOT NULL, old_status TEXT NOT NULL);
INSERT INTO trg17_members VALUES (1, 'Mira', 'active');
CREATE TRIGGER trg17_member_delete AFTER DELETE ON trg17_members BEGIN INSERT INTO trg17_member_deletes(member_id, member_name, old_status) VALUES (OLD.member_id, OLD.member_name, OLD.status); END;
DELETE FROM trg17_members WHERE member_id = 1;
SELECT member_id, member_name, old_status FROM trg17_member_deletes;

